	<?php foreach ( array( 'phone' => 'TELEFON', 'email' => 'E-POSTA', 'address' => 'ADRES' ) as $key => $label ) : $value = get_theme_mod( 'zm_' . $key ); if ( $value ) : ?><div class="contact-detail"><span><?php echo esc_html( $label ); ?></span><p><?php if ( 'phone' === $key ) : ?><a href="tel:<?php echo esc_attr( preg_replace( '/[^0-9+]/', '', $value ) ); ?>"><?php echo esc_html( $value ); ?></a><?php elseif ( 'email' === $key ) : ?><a href="mailto:<?php echo esc_attr( sanitize_email( $value ) ); ?>"><?php echo esc_html( $value ); ?></a><?php else : echo esc_html( $value ); endif; ?></p></div><?php endif; endforeach; ?>
