	<?php $contact_status = isset( $_GET['contact'] ) ? sanitize_key( wp_unslash( $_GET['contact'] ) ) : ''; if ( 'sent' === $contact_status ) : ?><p class="form-note form-success" role="status">Mesajınız alındı. En kısa sürede size dönüş yapacağız.</p><?php elseif ( 'stored' === $contact_status ) : ?><p class="form-note form-success" role="status">Mesajınız kaydedildi. E-posta bildirimi gönderilemedi ancak yönetim panelimizden size dönüş yapacağız.</p><?php elseif ( 'error' === $contact_status ) : ?><p class="form-note form-error" role="alert">Mesajınız kaydedilemedi. Lütfen daha sonra tekrar deneyin veya doğrudan iletişim kurun.</p><?php elseif ( 'invalid' === $contact_status ) : ?><p class="form-note form-error" role="alert">Formdaki alanları kontrol edip yeniden deneyin.</p><?php else : ?><p class="form-note">Mesajlar yönetim panelindeki Gelen Mesajlar bölümüne kaydedilir.</p><?php endif; ?></form></section>
